Examples
# In a package's R/jlbind.R, as use_jlbind() writes it
.onLoad &lt;- function(libname, pkgname) {
  jlbind::bind_client(pkgname)
}

Examples

# A package in a temporary directory
pkg &lt;- tempfile("mypkg")
dir.create(pkg)
writeLines(c("Package: mypkg", "Version: 0.1.0"), file.path(pkg, "DESCRIPTION"))

file &lt;- use_jlbind_ci(pkg)
#&gt; Wrote /tmp/RtmpnYyQQV/mypkg1adb338d70c/.github/workflows/R-CMD-check.yaml.
writeLines(readLines(file))
#&gt; # Generated by jlbind::use_jlbind_ci(), from r-lib/actions' check-standard
#&gt; # workflow: https://github.com/r-lib/actions/tree/v2/examples
#&gt; #
#&gt; # Runs R CMD check with Julia on Linux, Windows and macOS, after compiling the
#&gt; # package's Julia code into a library its tests and examples can call, and once
#&gt; # on Linux without Julia, which is what CRAN sees: the package must install and
#&gt; # pass its checks without the library.
#&gt; on:
#&gt;   push:
#&gt;     branches: [main, master]
#&gt;   pull_request:
#&gt; 
#&gt; name: R-CMD-check.yaml
#&gt; 
#&gt; permissions: read-all
#&gt; 
#&gt; jobs:
#&gt;   R-CMD-check:
#&gt;     runs-on: ${{ matrix.config.os }}
#&gt; 
#&gt;     name: ${{ matrix.config.os }} (${{ matrix.config.r }})${{ matrix.config.julia == '' && ' without Julia' || format(' Julia {0}', matrix.config.julia) }}
#&gt; 
#&gt;     strategy:
#&gt;       fail-fast: false
#&gt;       matrix:
#&gt;         config:
#&gt;           - {os: ubuntu-latest,   r: 'release', julia: 'nightly'}
#&gt;           - {os: windows-latest,  r: 'release', julia: 'nightly'}
#&gt;           - {os: macos-latest,    r: 'release', julia: 'nightly'}
#&gt;           - {os: ubuntu-latest,   r: 'release', julia: ''}
#&gt; 
#&gt;     env:
#&gt;       GITHUB_PAT: ${{ secrets.GITHUB_TOKEN }}
#&gt;       R_KEEP_PKG_SOURCE: yes
#&gt; 
#&gt;     steps:
#&gt;       - uses: actions/checkout@v7
#&gt; 
#&gt;       - uses: julia-actions/setup-julia@v3
#&gt;         if: matrix.config.julia != ''
#&gt;         with:
#&gt;           version: ${{ matrix.config.julia }}
#&gt; 
#&gt;       - uses: julia-actions/cache@v3
#&gt;         if: matrix.config.julia != ''
#&gt; 
#&gt;       - uses: r-lib/actions/setup-pandoc@v2
#&gt; 
#&gt;       - uses: r-lib/actions/setup-r@v2
#&gt;         with:
#&gt;           r-version: ${{ matrix.config.r }}
#&gt;           http-user-agent: ${{ matrix.config.http-user-agent }}
#&gt;           use-public-rspm: true
#&gt; 
#&gt;       - uses: r-lib/actions/setup-r-dependencies@v2
#&gt;         with:
#&gt;           extra-packages: any::rcmdcheck, BjarkeHautop/jlbind
#&gt;           needs: check
#&gt; 
#&gt;       # Compiles the package's Julia code into .jlbind/ and points
#&gt;       # JLBIND_LIBRARY at the library, so R CMD check binds the package to it.
#&gt;       - name: Compile the Julia library
#&gt;         if: matrix.config.julia != ''
#&gt;         shell: Rscript {0}
#&gt;         run: |
#&gt;           lib &lt;- jlbind::build_library()
#&gt;           cat(
#&gt;             "JLBIND_LIBRARY=", lib, "\n",
#&gt;             sep = "", file = Sys.getenv("GITHUB_ENV"), append = TRUE
#&gt;           )
#&gt; 
#&gt;       - uses: r-lib/actions/check-r-package@v2
